'use strict';
window.NexoServers=(()=>{
const KEY='nexo-infrastructure-v1',pages=['servers','proxies','server-order','process-monitor'];
let config={servers:[],proxies:[]},query='',size=10,current=1,sortKey='order',sortDir=1,processServer='';
const tokens=new Map(),samples=new Map(),health=new Map(),pending=new Map();let menuId=null,loadError='';
const q=s=>document.querySelector(s),E=s=>esc(s),n=(v,d=0)=>Number.isFinite(v)?v.toLocaleString('es-EC',{maximumFractionDigits:d}):'—';
function origin(value){const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash||!['','/'].includes(u.pathname))throw Error('Usa un origen HTTPS, sin ruta, credenciales ni parámetros.');return u.origin;}
function proxyURL(value){if(typeof value!=='string'||/[\x00-\x20]/.test(value)||value.length>4096)return false;try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password;}catch{return false;}}
function clean(x){if(!x||!Array.isArray(x.servers)||!Array.isArray(x.proxies)||x.servers.length>50||x.proxies.length>200)throw Error('Inventario inválido');const ids=new Set(),urls=new Set();const servers=x.servers.map((r,i)=>{if(!r||typeof r.id!=='string'||!r.id||ids.has(r.id)||typeof r.name!=='string'||!r.name.trim()||r.name.length>120)throw Error('Servidor inválido');ids.add(r.id);const url=origin(r.url);if(urls.has(url))throw Error('Dirección duplicada');urls.add(url);if(!Number.isInteger(r.limit)||r.limit<1||r.limit>1000000||!(r.capacity===null||(Number.isFinite(r.capacity)&&r.capacity>0&&r.capacity<=1000000)))throw Error('Límites inválidos');return {id:r.id,name:r.name,url,address:String(r.address||'').slice(0,200),limit:r.limit,capacity:r.capacity,order:i+1};});const pids=new Set();const proxies=x.proxies.map(r=>{if(!r||typeof r.id!=='string'||pids.has(r.id)||typeof r.name!=='string'||!r.name.trim()||r.name.length>120||!servers.some(s=>s.id===r.serverId)||!proxyURL(r.url))throw Error('Proxy inválido');pids.add(r.id);return {id:r.id,name:r.name,serverId:r.serverId,url:r.url};});return {servers,proxies};}
try{const raw=localStorage.getItem(KEY);if(raw)config=clean(JSON.parse(raw));}catch{loadError='No se pudo leer el inventario guardado. Exporta un respaldo antes de reemplazar los registros.';}
function save(next){try{next=clean(next);localStorage.setItem(KEY,JSON.stringify(next));config=next;loadError='';return true;}catch(e){toast('No se pudo guardar: '+e.message);return false;}}
function isDemo(){return window.NexoMonitor?.current().mode==='demo';}
function demoSnapshot(id){if(!id||id==='demo:all'){const a=demoSnapshot('demo:primary'),b=demoSnapshot('demo:secondary'),d=NexoCore.demo();d.server={...d.server,id:'demo:all',name:'Demo Servers (2)',cpu_count:32,uptime_seconds:null};d.cpu.percent=7;d.memory.total_bytes*=2;d.memory.used_percent=27.5;d.memory.used_bytes=d.memory.total_bytes*.275;d.memory.available_bytes=d.memory.total_bytes-d.memory.used_bytes;d.memory.shmem_bytes=a.memory.shmem_bytes+b.memory.shmem_bytes;d.memory.swap_total_bytes=a.memory.swap_total_bytes+b.memory.swap_total_bytes;d.cpu.load_average=a.cpu.load_average.map((v,i)=>v+b.cpu.load_average[i]);d.cpu.runnable_tasks=a.cpu.runnable_tasks+b.cpu.runnable_tasks;d.disks=d.disks.map(v=>({...v,total_bytes:v.total_bytes*2,used_bytes:v.used_bytes*2,available_bytes:v.available_bytes*2}));d.network={...d.network,rx_bps:119e6,tx_bps:2e6,capacity_bps:2e9,interfaces:[{name:'main/eth0',rx_bps:2e6,tx_bps:0},{name:'secondary/eth0',rx_bps:117e6,tx_bps:2e6}]};d.connections={...b.connections};d.sessions=b.sessions;return d;}if(!id.startsWith('demo:'))return null;const second=id==='demo:secondary',d=NexoCore.demo();d.server={...d.server,id,name:second?'Secondary Server · demo':'Main Server · demo'};d.cpu.percent=second?8:6;d.memory.used_percent=second?42:13;d.memory.used_bytes=d.memory.total_bytes*d.memory.used_percent/100;d.memory.available_bytes=d.memory.total_bytes-d.memory.used_bytes;d.connections.established=second?1:0;d.connections.peers=second?[{ip:'203.0.113.10',count:1}]:[];d.sessions=second?d.sessions.slice(0,1):[];d.network.tx_bps=second?2e6:0;d.network.rx_bps=second?117e6:2e6;d.network.interfaces=[{name:'eth0',rx_bps:d.network.rx_bps,tx_bps:d.network.tx_bps}];d.processes=[{pid:1001,name:'ffmpeg · demo',cpu_percent:second?4:2,rss_bytes:210*1024**2},{pid:1002,name:'nginx · demo',cpu_percent:1,rss_bytes:30*1024**2}];d.processes_status='available';return d;}
function rows(){if(isDemo())return [{id:'demo:primary',name:'Main Server',url:'https://primary.example.invalid',address:'192.0.2.10',order:1,limit:1000,capacity:1000},{id:'demo:secondary',name:'Secondary Server',url:'https://secondary.example.invalid',address:'192.0.2.11',order:2,limit:1000,capacity:1000}];return config.servers;}
function sample(id){return isDemo()?demoSnapshot(id):samples.get(id);}
function status(id){if(isDemo())return {online:true,label:'Demostración',latency:id==='demo:secondary'?2:0};const d=samples.get(id),h=health.get(id)||{};const fresh=d&&Date.now()-Date.parse(d.timestamp)<=20000,connected=tokens.has(id);return {online:!!(fresh&&connected&&!h.error),label:!connected?'Sin conectar':h.error?'Sin respuesta':fresh?'En directo':'Conectando',latency:h.latency,error:h.error};}
function record(url,data,token,latency){if(!url)return;let row=config.servers.find(s=>s.url===url);if(!row){const next=structuredClone(config);row={id:cryptoID(),name:data.server.name.slice(0,120),url:origin(url),address:new URL(url).hostname,limit:1000,capacity:data.network.capacity_bps?data.network.capacity_bps/1e6:null,order:next.servers.length+1};next.servers.push(row);if(!save(next))return;}if(token)tokens.set(row.id,token);samples.set(row.id,data);health.set(row.id,{latency:latency??health.get(row.id)?.latency,error:''});if(pages.includes(location.hash.slice(1)))render();}
function cryptoID(){return Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');}
async function poll(row){if(!tokens.has(row.id)||pending.has(row.id))return;const active=NexoMonitor.current();if(active.mode==='live'&&active.url===row.url&&!active.paused)return;const control=new AbortController(),token=tokens.get(row.id),endpoint=row.url;pending.set(row.id,control);const timeout=setTimeout(()=>control.abort(),4000),start=performance.now();try{const r=await fetch(endpoint+'/v1/snapshot',{headers:{Authorization:'Bearer '+token},credentials:'omit',redirect:'error',cache:'no-store',referrerPolicy:'no-referrer',signal:control.signal});if(!r.ok)throw Error('HTTP '+r.status);if(Number(r.headers.get('content-length'))>3e6)throw Error('Respuesta excesiva');const body=await r.text();if(body.length>3e6)throw Error('Respuesta excesiva');const d=NexoCore.snapshot(JSON.parse(body));if(tokens.get(row.id)!==token||!config.servers.some(s=>s.id===row.id&&s.url===endpoint))return;samples.set(row.id,d);health.set(row.id,{latency:performance.now()-start,error:''});}catch(e){if(tokens.get(row.id)===token)health.set(row.id,{...health.get(row.id),error:e.name==='AbortError'?'Tiempo de espera agotado':e.message});}finally{clearTimeout(timeout);pending.delete(row.id);if(pages.includes(location.hash.slice(1)))render();}}
function watch(){config.servers.forEach(poll);}
function gauge(value){if(!Number.isFinite(value))return '<span class="unknown-gauge">—</span>';const color=value>=95?'#e77681':value>=80?'#f4ce68':'#20b69d';return `<svg viewBox="0 0 60 60" class="server-gauge" role="img" aria-label="${n(value,1)} por ciento"><circle cx="30" cy="30" r="22" fill="none" stroke="#e9eff3" stroke-width="8"/><circle cx="30" cy="30" r="22" fill="none" stroke="${color}" stroke-width="8" stroke-dasharray="${value/100*138.23} 138.23" transform="rotate(-90 30 30)"/><text x="30" y="33" text-anchor="middle" font-size="10" fill="${color}">${n(value)}%</text></svg>`;}
function mb(v){return Number.isFinite(v)?n(v/1e6,1):'—';}
function info(){return (loadError?`<div class="monitor-error">${E(loadError)}</div>`:'')+(isDemo()?'<div class="demo-notice">DEMOSTRACIÓN · Servidores, IP, porcentajes y procesos simulados. No se consulta ninguna de estas direcciones.</div>':'');}
function toolbar(){return `<div class="server-table-toolbar"><label>Show <select id="server-page-size" aria-label="Filas por página">${[10,25,50].map(v=>`<option ${v===size?'selected':''}>${v}</option>`).join('')}</select> entries</label><label>Search: <input id="server-search" aria-label="Buscar servidores" value="${E(query)}" type="search"></label></div>`;}
function compare(a,b){let av=a[sortKey],bv=b[sortKey];if(sortKey==='status'){av=status(a.id).online?1:0;bv=status(b.id).online?1:0;}if(['connections','cpu','memory','latency'].includes(sortKey)){const sa=sample(a.id),sb=sample(b.id);av={connections:sa?.connections.established,cpu:sa?.cpu.percent,memory:sa?.memory?.used_percent,latency:status(a.id).latency}[sortKey];bv={connections:sb?.connections.established,cpu:sb?.cpu.percent,memory:sb?.memory?.used_percent,latency:status(b.id).latency}[sortKey];}if(av==null)return bv==null?0:1;if(bv==null)return -1;return (typeof av==='number'?av-bv:String(av).localeCompare(String(bv)))*sortDir;}
function serverTable(){const all=rows().filter(r=>(r.name+' '+r.address+' '+r.url).toLowerCase().includes(query.toLowerCase())).sort(compare);const count=Math.max(1,Math.ceil(all.length/size));current=Math.min(current,count);const visible=all.slice((current-1)*size,current*size);const columns=[['order','ORDER'],['status','STATUS'],['','PROXIED'],['name','SERVER NAME'],['address','SERVER IP / HOST'],['connections','CONNECTIONS'],['','NETWORK'],['cpu','CPU %'],['memory','MEM %'],['latency','PING / HTTP'],['','VERSION'],['','ACTIONS']];return `<div class="table-wrap server-table-wrap"><table class="server-table"><thead><tr>${columns.map(([k,label])=>`<th>${k?`<button data-server-sort="${k}">${label}<span>${sortKey===k?(sortDir===1?'↑':'↓'):'↕'}</span></button>`:label}</th>`).join('')}</tr></thead><tbody>${visible.length?visible.map(row=>{const d=sample(row.id),st=status(row.id);return `<tr class="${!st.online&&d?'stale-row':''}"><td>${row.order}</td><td><span class="server-state-square ${st.online?'up':'down'}" title="${E(st.label)}" role="img" aria-label="${E(st.label)}"></span></td><td><span class="proxy-state-square" title="Proxy no verificado; las definiciones locales son borradores" role="img" aria-label="Proxy no verificado"></span></td><td class="server-name-cell"><button class="server-name-link" data-server="resources" data-id="${E(row.id)}">${E(row.name)}</button><small>${E(new URL(row.url).hostname)}</small>${!st.online?`<small class="server-error">${E(st.label)}${d?' · última muestra':''}</small>`:''}</td><td>${E(row.address||'—')}</td><td><span class="network-badge">${n(d?.connections.established)}</span><small title="Capacidad registrada; todavía no se aplica al streaming">of ${n(row.limit)}</small></td><td><span class="network-badge">${mb(d?.network.tx_bps)} ↑ &nbsp; ${mb(d?.network.rx_bps)} ↓</span><small>${row.capacity?n(row.capacity)+' Mbps (config.)':d?.network.capacity_bps?mb(d.network.capacity_bps)+' Mbps':'Capacidad sin configurar'}</small></td><td>${gauge(d?.cpu.percent)}</td><td>${gauge(d?.memory?.used_percent)}</td><td><span class="server-version" title="Duración de consulta HTTPS; no es ping ICMP">${Number.isFinite(st.latency)?n(st.latency)+' ms':'—'}</span></td><td><span class="server-version" title="Versión del agente de monitorización">${E(d?.agent_version||'—')}</span></td><td><button class="server-actions-trigger" data-server="actions" data-id="${E(row.id)}" aria-label="Server Tools: ${E(row.name)}" aria-expanded="${menuId===row.id}">≡</button></td></tr>`;}).join(''):'<tr><td colspan="12" class="server-table-empty"><strong>No servers found</strong><p>Añade un servidor y conecta su agente HTTPS para recibir métricas reales.</p><button data-server="add" class="install-server">Install Server</button></td></tr>'}</tbody></table></div><div class="server-table-footer"><span>Showing ${all.length?(current-1)*size+1:0} to ${Math.min(current*size,all.length)} of ${all.length} entries</span><div class="pagination"><button data-server="previous" ${current===1?'disabled':''} aria-label="Página anterior">‹</button><span>${current}</span><button data-server="next" ${current===count?'disabled':''} aria-label="Página siguiente">›</button></div></div>`;}
function servers(){return info()+`<section class="panel servers-panel">${toolbar()}<div id="server-table-results">${serverTable()}</div></section><div class="servers-explanation"><p>Conexiones = sockets TCP. CPU y RAM proceden del agente; PING / HTTP mide la consulta HTTPS. Los valores sin medir muestran —.</p><p>Los límites y proxies guardados son configuración local. Las acciones de control de streaming requieren integrar el servicio IPTV.</p></div>`;}
function proxies(){return info()+`<section class="panel"><div class="panel-top"><div><h2>Manage Proxies</h2><p>Definiciones locales · pendientes de despliegue y verificación</p></div><button data-server="add-proxy" class="install-server">Add Proxy</button></div><div class="table-wrap"><table><thead><tr><th>PROXY NAME</th><th>ENDPOINT</th><th>UPSTREAM SERVER</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${config.proxies.length?config.proxies.map(p=>`<tr><td>${E(p.name)}</td><td>${E(p.url)}</td><td>${E(config.servers.find(s=>s.id===p.serverId)?.name)}</td><td><span class="badge muted">Borrador · no desplegado</span></td><td><button data-server="edit-proxy" data-id="${E(p.id)}">Edit</button></td></tr>`).join(''):'<tr><td colspan="5" class="server-table-empty"><strong>No proxies configured</strong><p>Registrar un proxy no cambia Nginx ni activa su uso en los servidores.</p></td></tr>'}</tbody></table></div></section>`;}
function orderView(){return `<section class="panel"><div class="panel-top"><div><h2>Server Order</h2><p>Orden del inventario local. No modifica la distribución de streams.</p></div><button data-server="export">Export inventory</button></div><div class="server-order-list">${config.servers.length?config.servers.map((s,i)=>`<div class="server-order-row"><span>${i+1}</span><strong>${E(s.name)}</strong><small>${E(s.address||new URL(s.url).hostname)}</small><button data-server="up" data-id="${E(s.id)}" ${i===0?'disabled':''} aria-label="Subir ${E(s.name)}">↑</button><button data-server="down" data-id="${E(s.id)}" ${i===config.servers.length-1?'disabled':''} aria-label="Bajar ${E(s.name)}">↓</button></div>`).join(''):'<div class="empty"><h3>No servers configured</h3><p>Añade servidores desde Manage Servers.</p></div>'}</div></section>`;}
function processes(){const list=rows();if(!list.some(s=>s.id===processServer))processServer=list[0]?.id||'';const d=sample(processServer),st=status(processServer);const procs=d?.processes_status==='unavailable'?undefined:d?.processes;return info()+`<section class="panel"><div class="panel-top"><div><h2>Process Monitor</h2><p>Lectura de procesos · sin controles para terminar o reiniciar</p></div><label class="process-server-label">Server <select id="process-server" aria-label="Seleccionar servidor de procesos">${list.map(s=>`<option value="${E(s.id)}" ${s.id===processServer?'selected':''}>${E(s.name)}</option>`).join('')}</select></label></div>${!st.online&&d?'<div class="monitor-error">La muestra está desactualizada. Los procesos mostrados pueden haber cambiado.</div>':''}<div class="table-wrap"><table><thead><tr><th>PID</th><th>PROCESS</th><th>CPU % (CAPACIDAD TOTAL)</th><th>RAM (MiB)</th></tr></thead><tbody>${procs?.length?procs.map(p=>`<tr><td>${E(p.pid)}</td><td>${E(p.name)}</td><td>${n(p.cpu_percent,2)}%</td><td>${Number.isFinite(p.rss_bytes)?n(p.rss_bytes/1024**2,1):'—'}</td></tr>`).join(''):`<tr><td colspan="4" class="server-table-empty"><strong>${procs?'No processes reported':'No process metrics available'}</strong><p>Conecta el agente actualizado para recibir PID, nombre, CPU y RAM. No se recopilan argumentos ni variables de entorno.</p></td></tr>`}</tbody></table></div><div class="server-table-footer"><span>${procs?n(procs.length)+' procesos visibles · '+E(d.processes_status||'available'):'Sin datos recibidos'}</span><span>Muestra ${d?E(new Date(d.timestamp).toLocaleTimeString('es-EC')):'—'}</span></div></section>`;}
function render(){const page=location.hash.slice(1);if(!pages.includes(page))return;const active=document.activeElement,caret=active?.id==='server-search'?{s:active.selectionStart,e:active.selectionEnd}:null;if(active?.id==='server-page-size')return;q('#view').innerHTML=page==='servers'?servers():page==='proxies'?proxies():page==='server-order'?orderView():processes();const input=q('#server-search');if(input)input.oninput=e=>{query=e.target.value;current=1;q('#server-table-results').innerHTML=serverTable();};if(caret&&input){input.focus({preventScroll:true});input.setSelectionRange(caret.s,caret.e);}const psize=q('#server-page-size');if(psize)psize.onchange=e=>{size=Number(e.target.value);current=1;q('#server-table-results').innerHTML=serverTable();};const proc=q('#process-server');if(proc)proc.onchange=e=>{processServer=e.target.value;render();};}
function editor(id,proxy=false){if(isDemo()&&id?.startsWith('demo:')){toast('Los servidores de demostración no se guardan ni se editan.');return;}if(proxy&&!config.servers.length){toast('Añade primero el servidor upstream.');return;}const row=(proxy?config.proxies:config.servers).find(s=>s.id===id)||{};q('#infra-save').textContent=proxy?'Save Proxy':'Save Server';q('#server-editor-title').textContent=proxy?(id?'Edit Proxy':'Add Proxy'):(id?'Edit Server':'Install Server · Connect Agent');q('#server-editor-fields').innerHTML=`<label for="infra-name">${proxy?'Proxy':'Server'} name</label><input id="infra-name" name="name" required maxlength="120" value="${E(row.name||'')}"><label for="infra-url">${proxy?'Proxy endpoint':'Agent HTTPS origin'}</label><input id="infra-url" name="url" type="url" required value="${E(row.url||'')}" placeholder="https://metricas.tu-dominio.com">${proxy?`<label for="infra-server">Upstream server</label><select id="infra-server" name="serverId">${config.servers.map(s=>`<option value="${E(s.id)}" ${s.id===row.serverId?'selected':''}>${E(s.name)}</option>`).join('')}</select><p class="help">Se guarda un borrador. No se despliega el proxy ni se cambian reglas de red.</p>`:`<label for="infra-address">Server IP / host (opcional)</label><input id="infra-address" name="address" maxlength="200" value="${E(row.address||'')}"><div class="infra-form-grid"><div><label for="infra-limit">Connection capacity (config.)</label><input id="infra-limit" name="limit" type="number" min="1" max="1000000" required value="${row.limit||1000}"></div><div><label for="infra-capacity">Link capacity · Mbps</label><input id="infra-capacity" name="capacity" type="number" min="1" max="1000000" value="${row.capacity||''}"></div></div><label for="infra-token">Read token (opcional)</label><input id="infra-token" name="token" type="password" autocomplete="off" minlength="32" maxlength="4096" placeholder="Token del agente; solo en memoria"><p class="help">El token se envía solo al origen HTTPS indicado y se borra al recargar. Guardar sin token registra el servidor sin conectarlo. Esta pantalla no instala software remoto.</p><a href="downloads/nexo-monitor.zip" download class="inline">Download Linux agent and installation guide</a>`}`;q('#infra-error').textContent='';q('#server-editor-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),next=structuredClone(config);const name=f.get('name').trim();if(!name)throw Error('Escribe un nombre.');const url=proxy?f.get('url').trim():origin(f.get('url').trim());if(proxy&&!proxyURL(url))throw Error('URL HTTP o HTTPS inválida o con credenciales.');const updated=proxy?{id:id||cryptoID(),name,url,serverId:f.get('serverId')}:{id:id||cryptoID(),name,url,address:f.get('address').trim()||new URL(url).hostname,limit:Number(f.get('limit')),capacity:f.get('capacity')?Number(f.get('capacity')):null,order:row.order||next.servers.length+1};const token=proxy?'':f.get('token').trim();if(token&&(token.length<32||token.length>4096||!/^[\x21-\x7E]+$/.test(token)))throw Error('Token inválido; mínimo 32 caracteres ASCII sin espacios.');const items=proxy?'proxies':'servers';if(id)next[items]=next[items].map(s=>s.id===id?updated:s);else next[items].push(updated);if(!save(next))return;if(!proxy){if(row.url&&row.url!==url){pending.get(updated.id)?.abort();tokens.delete(updated.id);samples.delete(updated.id);health.delete(updated.id);if(NexoMonitor.current().url===row.url)NexoMonitor.disconnect();}if(token){tokens.set(updated.id,token);poll(updated);}}q('#server-editor').close();render();toast(proxy?'Proxy guardado como borrador':'Servidor guardado');}catch(err){q('#infra-error').textContent=err.message;}};q('#server-editor').showModal();}
function showMenu(id,button){menuId=id;const popup=q('#server-action-menu');const demo=id.startsWith('demo:');popup.innerHTML=`<strong>Server Tools</strong><button data-server="processes" data-id="${E(id)}">Process Monitor</button><button data-server="resources" data-id="${E(id)}">View Resources</button><hr>${['Restart Live Streams','Start All Streams','Stop All Streams','Kill Connections'].map(t=>`<button disabled title="Requiere el servicio de control IPTV; el agente actual solo permite lectura">${t}</button>`).join('')}<button data-server="edit" data-id="${E(id)}" ${demo?'disabled':''}>Edit Server</button><button disabled title="Requiere desplegar y verificar un proxy real">Enable Proxy</button><small>Controles de streaming pendientes de integración.</small>`;popup.hidden=false;const r=button.getBoundingClientRect();popup.style.right=Math.max(12,innerWidth-r.right)+'px';popup.style.top=Math.max(10,Math.min(r.bottom+4,innerHeight-popup.offsetHeight-12))+'px';button.setAttribute('aria-expanded','true');}
function openResources(id){if(id.startsWith('demo:')){NexoMonitor.showDemoServer(id);location.hash='recursos';return;}const row=config.servers.find(r=>r.id===id);if(!row)return;if(!tokens.has(id)){editor(id);toast('Introduce el token de lectura para abrir los recursos.');return;}NexoMonitor.useServer(row.url,tokens.get(id));location.hash='recursos';}
function closeMenu(){menuId=null;q('#server-action-menu').hidden=true;document.querySelectorAll('.server-actions-trigger').forEach(b=>b.setAttribute('aria-expanded','false'));}
document.addEventListener('click',e=>{const b=e.target.closest('[data-server],[data-server-sort]');if(!b){if(!e.target.closest('#server-action-menu'))closeMenu();return;}if(b.dataset.serverSort){const k=b.dataset.serverSort;sortDir=sortKey===k?-sortDir:1;sortKey=k;q('#server-table-results').innerHTML=serverTable();return;}const id=b.dataset.id,action=b.dataset.server;if(action!=='actions')closeMenu();if(action==='actions')showMenu(id,b);if(action==='add')editor();if(action==='edit')editor(id);if(action==='add-proxy')editor(null,true);if(action==='edit-proxy')editor(id,true);if(action==='close-editor')q('#server-editor').close();if(action==='resources')openResources(id);if(action==='processes'){processServer=id;location.hash='process-monitor';if(location.hash==='#process-monitor')render();}if(action==='previous'){current=Math.max(1,current-1);q('#server-table-results').innerHTML=serverTable();}if(action==='next'){current++;q('#server-table-results').innerHTML=serverTable();}if(action==='up'||action==='down'){const next=structuredClone(config),i=next.servers.findIndex(s=>s.id===id),j=i+(action==='up'?-1:1);if(i>=0&&j>=0&&j<next.servers.length){[next.servers[i],next.servers[j]]=[next.servers[j],next.servers[i]];if(save(next))render();}}if(action==='export')download('nexo-infrastructure-'+today()+'.json',JSON.stringify(config,null,2),'application/json');});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
document.addEventListener('DOMContentLoaded',()=>{q('#server-editor').addEventListener('close',()=>{const t=q('#infra-token');if(t)t.value='';});setInterval(()=>{watch();if(pages.includes(location.hash.slice(1)))render();},5000);});
return {disconnectURL:url=>{for(const r of config.servers)if(r.url===url){pending.get(r.id)?.abort();tokens.delete(r.id);health.set(r.id,{latency:health.get(r.id)?.latency});}},failURL:(url,error)=>{const r=config.servers.find(s=>s.url===url);if(r)health.set(r.id,{...health.get(r.id),error});},isPage:p=>pages.includes(p),render,editor,record,demoSnapshot,clean,rows,exportConfig:()=>structuredClone(config)};
})();
